    "res_bc_anke.1": { en: "Did you know? The moon pulls on the sea. That makes the tides.", t: [["你", "nǐ", "you"], ["知道", "zhīdao", "know"], ["吗", "ma", "(question)"], ["？", "", ""], ["月亮", "yuèliang", "moon"], ["在", "zài", "(ongoing)"], ["拉", "lā", "pull"], ["大海", "dàhǎi", "sea"], ["。", "", ""], ["所以", "suǒyǐ", "so"], ["有", "yǒu", "there are"], ["涨潮", "zhǎngcháo", "high tide"], ["和", "hé", "and"], ["退潮", "tuìcháo", "low tide"], ["。", "", ""]] },
    "res_bc_anke.2": { en: "Twice a day the water comes, twice a day it goes. Every day about fifty minutes later.", t: [["水", "shuǐ", "water"], ["一", "yì", "one"], ["天", "tiān", "day"], ["来", "lái", "comes"], ["两", "liǎng", "two"], ["次", "cì", "times"], ["，", "", ""], ["走", "zǒu", "goes"], ["两", "liǎng", "two"], ["次", "cì", "times"], ["。", "", ""], ["每天", "měitiān", "every day"], ["晚", "wǎn", "later"], ["五十", "wǔshí", "fifty"], ["分钟", "fēnzhōng", "minutes"], ["左右", "zuǒyòu", "about"], ["。", "", ""]] },
    "res_bc_anke.3": { en: "At full moon the tides are especially high.", t: [["月亮", "yuèliang", "moon"], ["圆", "yuán", "round"], ["的", "de", "(particle)"], ["时候", "shíhou", "when"], ["，", "", ""], ["潮水", "cháoshuǐ", "tide"], ["特别", "tèbié", "especially"], ["高", "gāo", "high"], ["。", "", ""]] },
    "res_bc_wilhelm.1": { en: "I was born on this beach, eighty years ago.", t: [["八十", "bāshí", "eighty"], ["年", "nián", "years"], ["前", "qián", "ago"], ["，", "", ""], ["我", "wǒ", "I"], ["在", "zài", "on"], ["这", "zhè", "this"], ["个", "ge", "(measure word)"], ["海滩", "hǎitān", "beach"], ["出生", "chūshēng", "was born"], ["。", "", ""]] },
    "res_bc_wilhelm.2": { en: "Sea turtles swim thousands of kilometres. But to lay eggs, they come back to the beach where they were born.", t: [["海龟", "hǎiguī", "sea turtles"], ["游", "yóu", "swim"], ["几千", "jǐqiān", "thousands"], ["公里", "gōnglǐ", "kilometres"], ["。", "", ""], ["可是", "kěshì", "but"], ["生", "shēng", "lay"], ["蛋", "dàn", "eggs"], ["的", "de", "(particle)"], ["时候", "shíhou", "when"], ["，", "", ""], ["它们", "tāmen", "they"], ["回到", "huídào", "return to"], ["出生", "chūshēng", "birth"], ["的", "de", "(particle)"], ["海滩", "hǎitān", "beach"], ["。", "", ""]] },
    "res_bc_wilhelm.3": { en: "Please no lights on the beach at night. The little turtles go to the brightest light: that should be the sea.", t: [["晚上", "wǎnshang", "at night"], ["请", "qǐng", "please"], ["不要", "búyào", "don't"], ["在", "zài", "on"], ["海滩", "hǎitān", "beach"], ["开灯", "kāidēng", "turn on lights"], ["。", "", ""], ["小", "xiǎo", "little"], ["海龟", "hǎiguī", "turtles"], ["往", "wǎng", "towards"], ["亮", "liàng", "bright"], ["的", "de", "(particle)"], ["地方", "dìfang", "place"], ["走", "zǒu", "go"], ["，", "", ""], ["那", "nà", "that"], ["应该", "yīnggāi", "should be"], ["是", "shì", "is"], ["大海", "dàhǎi", "sea"], ["。", "", ""]] },
    "res_bc_rosa.1": { en: "Welcome to my café! Have a glass of water... but not from the sea!", t: [["欢迎", "huānyíng", "welcome"], ["来", "lái", "to come to"], ["我", "wǒ", "my"], ["的", "de", "'s"], ["咖啡馆", "kāfēiguǎn", "café"], ["！", "", ""], ["喝", "hē", "drink"], ["杯", "bēi", "glass"], ["水", "shuǐ", "water"], ["吧", "ba", "(suggestion)"], ["…", "", ""], ["可", "kě", "but"], ["不是", "búshì", "not"], ["海水", "hǎishuǐ", "seawater"], ["！", "", ""]] },
    "res_bc_rosa.2": { en: "Why is the sea salty? Rivers carry a little salt from the rocks to the sea. The sun takes the water, but the salt stays.", t: [["海水", "hǎishuǐ", "seawater"], ["为什么", "wèishénme", "why"], ["是", "shì", "is"], ["咸", "xián", "salty"], ["的", "de", "(particle)"], ["？", "", ""], ["河", "hé", "rivers"], ["把", "bǎ", "(object marker)"], ["石头", "shítou", "rocks"], ["里", "lǐ", "in"], ["的", "de", "(particle)"], ["盐", "yán", "salt"], ["带", "dài", "carry"], ["到", "dào", "to"], ["海里", "hǎilǐ", "the sea"], ["。", "", ""], ["太阳", "tàiyáng", "sun"], ["把", "bǎ", "(object marker)"], ["水", "shuǐ", "water"], ["晒", "shài", "dries"], ["走", "zǒu", "away"], ["，", "", ""], ["盐", "yán", "salt"], ["留", "liú", "stays"], ["下来", "xiàlai", "behind"], ["。", "", ""]] },
    "res_bc_rosa.3": { en: "Millions of years of rivers: that's a lot of salt!", t: [["几百万", "jǐbǎiwàn", "millions"], ["年", "nián", "years"], ["的", "de", "of"], ["河水", "héshuǐ", "river water"], ["：", "", ""], ["那", "nà", "that"], ["是", "shì", "is"], ["很", "hěn", "very"], ["多", "duō", "much"], ["盐", "yán", "salt"], ["！", "", ""]] },
    "res_bc_konrad.1": { en: "I paint the sea every day. And it's a different blue every day!", t: [["我", "wǒ", "I"], ["每天", "měitiān", "every day"], ["画", "huà", "paint"], ["大海", "dàhǎi", "sea"], ["。", "", ""], ["每天", "měitiān", "every day"], ["的", "de", "'s"], ["蓝色", "lánsè", "blue"], ["都", "dōu", "all"], ["不", "bù", "not"], ["一样", "yíyàng", "same"], ["！", "", ""]] },
    "res_bc_konrad.2": { en: "Water swallows red light, but the blue light comes back. That's why deep water looks blue.", t: [["水", "shuǐ", "water"], ["会", "huì", "can"], ["吃", "chī", "swallow"], ["掉", "diào", "(away)"], ["红色", "hóngsè", "red"], ["的", "de", "(particle)"], ["光", "guāng", "light"], ["，", "", ""], ["蓝色", "lánsè", "blue"], ["的", "de", "(particle)"], ["光", "guāng", "light"], ["会", "huì", "will"], ["回来", "huílai", "come back"], ["。", "", ""], ["所以", "suǒyǐ", "so"], ["深", "shēn", "deep"], ["水", "shuǐ", "water"], ["是", "shì", "is"], ["蓝色", "lánsè", "blue"], ["的", "de", "(particle)"], ["。", "", ""]] },
    "res_bc_konrad.3": { en: "Over white sand the water is turquoise. Beautiful, isn't it?", t: [["白", "bái", "white"], ["沙子", "shāzi", "sand"], ["上面", "shàngmiàn", "above"], ["的", "de", "(particle)"], ["水", "shuǐ", "water"], ["是", "shì", "is"], ["绿蓝色", "lǜlánsè", "turquoise"], ["的", "de", "(particle)"], ["。", "", ""], ["很", "hěn", "very"], ["美", "měi", "beautiful"], ["吧", "ba", "(isn't it)"], ["？", "", ""]] },
